import urllib.request, concurrent.futures
root='https://raw.githubusercontent.com/NVIDIA/cuda-samples/db3eea23946bca2e90a75eca2b5b3e07158a9e11/Samples/5_Domain_Specific/MonteCarloMultiGPU/'
def get(name):
