  spans={'MonteCarloMultiGPU.cpp':[(260,330),(420,490)],'MonteCarlo_kernel.cu':[(120,180)],'CMakeLists.txt':[(1,120)]}[name]
  return name+'\\n'+'\\n'.join(f'{i}: {lines[i-1]}' for start,end in spans for i in range(start,min(end,len(lines))+1))
